def poly(a, d):
    from itertools import combinations_with_replacement
    return np.column_stack([np.ones(len(a))] + [np.prod(a[:, j], 1) for k in range(1, d + 1) for j in combinations_with_replacement(range(4), k)])

def kernel(a, b, par, family):
    dx = a[:, None, :] - b[None, :, :]
    r2 = np.einsum('ijk,k,ijk->ij', dx, np.exp(par[:4]), dx)
    if family == 'gauss':
        return np.exp(-r2)
    if family == 'rq':
        return 1 / (1 + r2)
    if family == 'mat52':
        r = np.sqrt(r2)
        return (1 + r + r2 / 3) * np.exp(-r)
    if family == 'mat72':
        r = np.sqrt(r2)
        return (1 + r + 0.4 * r2 + r2 * r / 15) * np.exp(-r)
    raise ValueError(family)

def _quadratic(x):
    from itertools import combinations_with_replacement
    return np.column_stack([np.ones(len(x)), x] + [x[:, i] * x[:, j] for (i, j) in combinations_with_replacement(range(x.shape[1]), 2)])

def solve_batch(study: dict) -> dict:
    from scipy.optimize import least_squares
    train = study['train']
    (x, xt) = (train['x'], study['test']['x'])
    t = study['eval_times']
    trajectories = train['traj'].T

    def basis(rates):
        return -np.expm1(-t[:, None] * rates)

    def project(b):
        return np.linalg.lstsq(b, trajectories, rcond=None)[0]

    def residual(rates):
        b = basis(rates)
        return (b @ project(b) - trajectories).ravel()
    rates = least_squares(residual, [1.5, 0.25], bounds=([0.7, 0.02], [4.0, 0.65])).x
    b = basis(rates)
    y_hat = _readout(x, xt, train['y'], 0.001)
    state_pred = _readout(x, xt, project(b).T, 0.006) @ b.T
    terminal = state_pred[:, -1]
    return {'y_hat': y_hat, 'state_pred': state_pred, 'diagnostics_vec': np.array([y_hat.mean(), y_hat.std(), terminal.mean(), terminal.std()])}
